  "element_review": {
    "selected_core_idea": "Mastercard, the architect of frictionless payment, publicly argues that speed isn't always the point and creates an unhurried checkout lane (with an optional 'Slow Tap' terminal moment) open to everyone, so the everyday act of paying becomes a place for human connection.",
    "candidate_elements": [
      {
        "element": "Merchant and cashier recognition: a 'knows its customers' acknowledgement for staff and stores that make the Slow Lane work, plus visible credit to cashiers.",
        "source": "C4",
        "purpose": "Makes cashiers the heroes, offsets the emotional labour risk, and gives merchants a reason to stay beyond the pilot. It borrows the warmth of the Regulars mark without turning it into a loyalty scheme.",
        "include": true,
        "reason": "The brief's main concern for C3 is that it must not add unpaid emotional labour. Recognition solves this directly and supports the core idea without replacing it. It is kept as staff recognition, not a customer-facing loyalty mechanic."
      },
      {
        "element": "Aggregate, anonymised insight on how many people have a place where they are known.",
        "source": "C4",
        "purpose": "Would give the campaign a data story and a loneliness statistic to publish.",
        "include": false,
        "reason": "It adds a data and privacy layer that conflicts with the idea's strength of needing no data targeting. Pilot results (conversation time, shopper and staff wellbeing, basket value) will supply the proof more simply."
      },
      {
        "element": "Refundable deposits or any payment-based commitment device for plans.",
        "source": "C1",
        "purpose": "Would help people follow through on social plans.",
